import React, { useEffect, useState } from "react";

function LevelList() {
  const [levels, setLevels] = useState([]);

  const fetchLevels = async () => {
    const res = await fetch("http://localhost:5000/levels");
    const data = await res.json();
    setLevels(data);
  };

  useEffect(() => {
    fetchLevels();
  }, []);

  const completeLevel = async (level) => {
    await fetch("http://localhost:5000/complete-level", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ level })
    });
    fetchLevels(); // refresh
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>🎮 Game Levels</h2>

      {levels.map((lvl) => (
        <div
          key={lvl.level}
          style={{
            margin: "10px",
            padding: "10px",
            border: "1px solid black",
            background:
              lvl.status === "completed"
                ? "#b6fcb6"
                : lvl.status === "open"
                ? "#d0e7ff"
                : "#eee"
          }}
        >
          <strong>Level {lvl.level}</strong> — {lvl.status.toUpperCase()}

          {lvl.status === "open" && (
            <button
              style={{ marginLeft: "10px" }}
              onClick={() => completeLevel(lvl.level)}
            >
              Complete Level
            </button>
          )}

          {lvl.status === "locked" && (
            <button disabled style={{ marginLeft: "10px" }}>
              🔒 Locked
            </button>
          )}
        </div>
      ))}
    </div>
  );
}

export default LevelList;
